use crate::aap::caps::kb_read;

/// Upper bound on the output question. Bounded in bytes, which also bounds
/// the character count, so the `len(question) <= 512` ensure holds under
/// either measure.
const MAX_QUESTION_BYTES: usize = 512;

fn bound_question(mut question: String) -> String {
    if question.len() <= MAX_QUESTION_BYTES {
        return question;
    }
    let mut end = MAX_QUESTION_BYTES;
    while !question.is_char_boundary(end) {
        end -= 1;
    }
    question.truncate(end);
    question
}

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;
        let question = bound_question(query.query.question);
        let knowledge: Vec<String> = kb_read::lookup(&question);

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
